    translation: '勤勉而喜好学习，不以向不如自己的人请教为耻。知道就是知道，不知道就是不知道，这才是真正的智慧。默默地记住所学的知识，学习不觉得满足，教诲别人不知疲倦。我曾经说过：读书有三到，就是心到、眼到、口到。心思不在书本上，那么眼睛就不会看仔细，心和眼既然不专心一意，却只是随随便便地读，就一定不能记住，即使记住了也不能长久。三到之中，心到最重要。心既然已经到了，眼和口难道会不到吗？读书人读书，第一要有志向，第二要有见识，第三要有恒心。有志向就决不会甘于做下等的人；有见识就知道学问没有穷尽，不敢因为一点心得就自满自足，像河伯观海、井蛙观天那样，都是没有见识的人；有恒心就决没有做不成的事情。这三样缺一不可。',
